<?php use VO\Support\Template; ob_start(); ?>
<p><a href="/">← Volver al catálogo</a></p><article class="detail"><h1><?= Template::e($item['name']) ?></h1><p><?= Template::e($item['description'] ?? '') ?></p><p class="price"><?= Template::e($item['display_price']) ?></p>
<?php if ($variants): ?><h2>Variantes</h2><ul><?php foreach ($variants as $v): ?><li><?= Template::e($v['name']) ?> — <?= Template::e($v['display_price']) ?></li><?php endforeach; ?></ul><?php endif; ?>
